solution.exercise.cpp:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
static bool leap(int y){return y%4==0&&(y%100!=0||y%400==0);}static int days(int y,int m){int d[]={31,28,31,30,31,30,31,31,30,31,30,31};return d[m-1]+(m==2&&leap(y));}static void next(date_time*d){if(++d->day>days(d->year,d->month)){d->day=1;if(++d->month==13){d->month=1;d->year++;}}}static void previous(date_time*d){if(--d->day==0){if(--d->month==0){d->month=12;d->year--;}d->day=days(d->year,d->month);}}static int weekday(date_time d){int y=d.year,m=d.month;if(m<3){m+=12;y--;}int h=(d.day+13*(m+1)/5+y+y/4-y/100+y/400)%7;return (h+5)%7;}bool delivery_date(date_time s,const char*t,date_time*out){*out=s;if(!strcmp(t,"NOW")){out->hour+=2;while(out->hour>=24){out->hour-=24;next(out);}return true;}out->minute=out->second=0;if(!strcmp(t,"ASAP")){if(s.hour<13)out->hour=17;else{next(out);out->hour=13;}return true;}if(!strcmp(t,"EOW")){int wd=weekday(s),target=wd<=2?4:6;out->hour=wd<=2?17:20;for(int i=wd;i<target;i++)next(out);return true;}if(t[0]=='Q'&&t[1]>='1'&&t[1]<='4'&&!t[2]){int q=t[1]-'0';out->year=s.year+((s.month-1)/3+1>q);out->month=q*3;out->day=days(out->year,out->month);out->hour=8;while(weekday(*out)>4)previous(out);return true;}char*end;long m=strtol(t,&end,10);if(m>=1&&m<=12&&*end=='M'&&!end[1]){out->year=s.year+(s.month>=m);out->month=(int)m;out->day=1;out->hour=8;while(weekday(*out)>4)next(out);return true;}return false;}

