{date_time start={2012,2,13,9,0,0},actual;assert(delivery_date(start,"NOW",&actual));assert(actual.year==2012);assert(actual.month==2);assert(actual.day==13);assert(actual.hour==11);assert(actual.minute==0);assert(actual.second==0);}
